def find_orfs(s):
    # returns (start0, end0_exclusive) of ATG..stop runs in given strand sequence
    out=[]
    n=len(s)
    for frame in range(3):
        i=frame
        start=None
        while i+3<=n:
            cod=s[i:i+3]
            if cod=='ATG' and start is None:
                start=i
            if cod in ('TAA','TAG','TGA') and start is not None:
                out.append((start,i+3))
                start=None
            i+=3
        if start is not None:
            out.append((start,n))
    return out

